FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "Auger cap" }
export const augerCap = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Cap diameter" }
        isLength(definition.capDiameter, { (millimeter) : [0, 29, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Cap depth" }
        isLength(definition.capDepth, { (millimeter) : [0, 25, 10000] } as LengthBoundSpec);
        annotation { "Name" : "End wall" }
        isLength(definition.endWall, { (millimeter) : [0, 2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Cap minor diameter" }
        isLength(definition.capMinorDiameter, { (millimeter) : [0, 23.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Thread pitch" }
        isLength(definition.threadPitch, { (millimeter) : [0, 3.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Thread major diameter" }
        isLength(definition.threadMajorDiameter, { (millimeter) : [0, 26, 10000] } as LengthBoundSpec);
