        annotation { "Name" : "Thread clearance" }
        isLength(definition.threadClearance, { (millimeter) : [0, 0.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Thread phase" }
        isLength(definition.threadPhase, { (millimeter) : [-0.4, -0.4, 10000] } as LengthBoundSpec);
    }
    {
    // Cap sketch
    var capSketchSk = newSketchOnPlane(context, id + "capSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(capSketchSk, "outline_0", { "start" : vector((0 * millimeter), -definition.capDepth), "end" : vector(definition.capDiameter / 2, -definition.capDepth) });
    skLineSegment(capSketchSk, "outline_1", { "start" : vector(definition.capDiameter / 2, -definition.capDepth), "end" : vector(definition.capDiameter / 2, (0 * millimeter)) });
    skLineSegment(capSketchSk, "outline_2", { "start" : vector(definition.capDiameter / 2, (0 * millimeter)), "end" : vector(definition.capDiameter / 2 - definition.endWall, definition.endWall) });
    skLineSegment(capSketchSk, "outline_3", { "start" : vector(definition.capDiameter / 2 - definition.endWall, definition.endWall), "end" : vector((0 * millimeter), definition.endWall) });
    skLineSegment(capSketchSk, "outline_4", { "start" : vector((0 * millimeter), definition.endWall), "end" : vector((0 * millimeter), -definition.capDepth) });
    skLineSegment(capSketchSk, "axis", { "start" : vector(0, 0) * millimeter, "end" : vector(0, 10) * millimeter, "construction" : true });
    skSolve(capSketchSk);
    // Cap
    opRevolve(context, id + "cap" + "tool", { "entities" : qSketchRegion(id + "capSketch"), "axis" : line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), "angleForward" : 360 * degree });
    // Thread plane
    // Thread helix sketch
    var threadHelixSketchSk = newSketchOnPlane(context, id + "threadHelixSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (definition.threadPhase - (8 * definition.threadPitch)) * vector(0, 0, 1), vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(threadHelixSketchSk, "circle", { "center" : vector(0, 0) * millimeter, "radius" : definition.capMinorDiameter / 2 });
    skSolve(threadHelixSketchSk);
    // Thread helix
    const hThreadHelixCircle = evCurveDefinition(context, { "edge" : sketchEntityQuery(id + "threadHelixSketch", EntityType.EDGE, "circle") });
    opHelix(context, id + "threadHelix", { "direction" : hThreadHelixCircle.coordSystem.zAxis, "axisStart" : hThreadHelixCircle.coordSystem.origin, "startPoint" : hThreadHelixCircle.coordSystem.origin + (hThreadHelixCircle.radius) * hThreadHelixCircle.coordSystem.xAxis, "interval" : [0, 10], "clockwise" : true, "helicalPitch" : definition.threadPitch, "spiralPitch" : 0 * meter });
    // Thread groove profile
    var threadGrooveProfileSk = newSketchOnPlane(context, id + "threadGrooveProfile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(threadGrooveProfileSk, "lowerFlank", { "start" : vector(definition.capMinorDiameter / 2 - (0.5 * millimeter), definition.threadPhase - (8 * definition.threadPitch) - ((1 * millimeter) + (definition.threadMinorDiameter / 2 - (definition.capMinorDiameter / 2 - (0.5 * millimeter))) / 6 + 1.013794 * definition.threadClearance)), "end" : vector(definition.threadMajorDiameter / 2 - (0.5 * millimeter) + 0.164399 * ((0.5 * millimeter) + definition.threadClearance), definition.threadPhase - (8 * definition.threadPitch) - ((0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12)) - (0.986394 * ((0.5 * millimeter) + definition.threadClearance))) });
    skArc(threadGrooveProfileSk, "lowerRound", { "start" : vector(definition.threadMajorDiameter / 2 - (0.5 * millimeter) + 0.164399 * ((0.5 * millimeter) + definition.threadClearance), definition.threadPhase - (8 * definition.threadPitch) - ((0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12)) - (0.986394 * ((0.5 * millimeter) + definition.threadClearance))), "mid" : arcMid(vector(definition.threadMajorDiameter / 2 - (0.5 * millimeter) + 0.164399 * ((0.5 * millimeter) + definition.threadClearance), definition.threadPhase - (8 * definition.threadPitch) - ((0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12)) - (0.986394 * ((0.5 * millimeter) + definition.threadClearance))), vector(definition.threadMajorDiameter / 2 + definition.threadClearance, definition.threadPhase - (8 * definition.threadPitch) - ((0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12))), 0.3666294295), "end" : vector(definition.threadMajorDiameter / 2 + definition.threadClearance, definition.threadPhase - (8 * definition.threadPitch) - ((0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12))) });
    skLineSegment(threadGrooveProfileSk, "bottom", { "start" : vector(definition.threadMajorDiameter / 2 + definition.threadClearance, definition.threadPhase - (8 * definition.threadPitch) - ((0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12))), "end" : vector(definition.threadMajorDiameter / 2 + definition.threadClearance, definition.threadPhase - (8 * definition.threadPitch) + (0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12)) });
    skArc(threadGrooveProfileSk, "upperRound", { "start" : vector(definition.threadMajorDiameter / 2 + definition.threadClearance, definition.threadPhase - (8 * definition.threadPitch) + (0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12)), "mid" : arcMid(vector(definition.threadMajorDiameter / 2 + definition.threadClearance, definition.threadPhase - (8 * definition.threadPitch) + (0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12)), vector(definition.threadMajorDiameter / 2 - (0.5 * millimeter) + 0.164399 * ((0.5 * millimeter) + definition.threadClearance), definition.threadPhase - (8 * definition.threadPitch) + (0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12) + 0.986394 * ((0.5 * millimeter) + definition.threadClearance)), 0.3666294295), "end" : vector(definition.threadMajorDiameter / 2 - (0.5 * millimeter) + 0.164399 * ((0.5 * millimeter) + definition.threadClearance), definition.threadPhase - (8 * definition.threadPitch) + (0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12) + 0.986394 * ((0.5 * millimeter) + definition.threadClearance)) });
    skLineSegment(threadGrooveProfileSk, "upperFlank", { "start" : vector(definition.threadMajorDiameter / 2 - (0.5 * millimeter) + 0.164399 * ((0.5 * millimeter) + definition.threadClearance), definition.threadPhase - (8 * definition.threadPitch) + (0.576436 * millimeter) - ((definition.threadMajorDiameter - definition.threadMinorDiameter) / 12) + 0.986394 * ((0.5 * millimeter) + definition.threadClearance)), "end" : vector(definition.capMinorDiameter / 2 - (0.5 * millimeter), definition.threadPhase - (8 * definition.threadPitch) + (1 * millimeter) + (definition.threadMinorDiameter / 2 - (definition.capMinorDiameter / 2 - (0.5 * millimeter))) / 6 + 1.013794 * definition.threadClearance) });
    skLineSegment(threadGrooveProfileSk, "inner", { "start" : vector(definition.capMinorDiameter / 2 - (0.5 * millimeter), definition.threadPhase - (8 * definition.threadPitch) + (1 * millimeter) + (definition.threadMinorDiameter / 2 - (definition.capMinorDiameter / 2 - (0.5 * millimeter))) / 6 + 1.013794 * definition.threadClearance), "end" : vector(definition.capMinorDiameter / 2 - (0.5 * millimeter), definition.threadPhase - (8 * definition.threadPitch) - ((1 * millimeter) + (definition.threadMinorDiameter / 2 - (definition.capMinorDiameter / 2 - (0.5 * millimeter))) / 6 + 1.013794 * definition.threadClearance)) });
    skSolve(threadGrooveProfileSk);
    // Thread groove
    opSweep(context, id + "threadGroove" + "tool", { "profiles" : qSketchRegion(id + "threadGrooveProfile"), "path" : qCreatedBy(id + "threadHelix", EntityType.EDGE) });
    opBoolean(context, id + "threadGroove" + "bool", { "tools" : qCreatedBy(id + "threadGroove" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "cap", EntityType.BODY), qCreatedBy(id + "threadGroove" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // End wall sketch
    var endWallSketchSk = newSketchOnPlane(context, id + "endWallSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(endWallSketchSk, "outline_0", { "start" : vector(0, 0) * millimeter, "end" : vector(definition.capDiameter / 2, (0 * millimeter)) });
    skLineSegment(endWallSketchSk, "outline_1", { "start" : vector(definition.capDiameter / 2, (0 * millimeter)), "end" : vector(definition.capDiameter / 2 - definition.endWall, definition.endWall) });
    skLineSegment(endWallSketchSk, "outline_2", { "start" : vector(definition.capDiameter / 2 - definition.endWall, definition.endWall), "end" : vector((0 * millimeter), definition.endWall) });
    skLineSegment(endWallSketchSk, "outline_3", { "start" : vector((0 * millimeter), definition.endWall), "end" : vector(0, 0) * millimeter });
    skSolve(endWallSketchSk);
    // End wall
    opRevolve(context, id + "endWall" + "tool", { "entities" : qSketchRegion(id + "endWallSketch"), "axis" : line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), "angleForward" : 360 * degree });
    opBoolean(context, id + "endWall" + "bool", { "tools" : qUnion([qSubtraction(qCreatedBy(id + "cap", EntityType.BODY), qCreatedBy(id + "endWall" + "tool", EntityType.BODY)), qCreatedBy(id + "endWall" + "tool", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
    // Bore sketch
    var boreSketchSk = newSketchOnPlane(context, id + "boreSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(boreSketchSk, "bore", { "center" : vector(0, 0) * millimeter, "radius" : definition.capMinorDiameter / 2 });
    skSolve(boreSketchSk);
    // Bore
    opExtrude(context, id + "bore" + "tool", { "entities" : qSketchRegion(id + "boreSketch"), "direction" : vector(-0, -0, -1), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "bore" + "bool", { "tools" : qCreatedBy(id + "bore" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "cap", EntityType.BODY), qCreatedBy(id + "bore" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "capSketch", EntityType.BODY), qCreatedBy(id + "threadHelixSketch", EntityType.BODY), qCreatedBy(id + "threadHelix", EntityType.BODY), qCreatedBy(id + "threadGrooveProfile", EntityType.BODY), qCreatedBy(id + "endWallSketch", EntityType.BODY), qCreatedBy(id + "boreSketch", EntityType.BODY)]) });
    });
